import java.io.BufferedInputStream
import java.io.BufferedOutputStream
import java.io.InputStream
import java.io.OutputStream

const val INF = 1000000001

data class Pair(val first: Int, val second: Int)

fun sort(arr: IntArray): IntArray {
    fun quickSort(leftBound: Int, rightBound: Int) {
        if (rightBound - leftBound < 1) return

        var left = leftBound
        val pivot = leftBound + (rightBound - leftBound + 1) / 2

        arr[pivot] = arr[rightBound].also { arr[rightBound] = arr[pivot] }

        for (i in leftBound..rightBound) {
            if (arr[i] < arr[rightBound]) {
                arr[i] = arr[left].also { arr[left] = arr[i] }
                left++
            }
        }

        arr[left] = arr[rightBound].also { arr[rightBound] = arr[left] }

        quickSort(leftBound, left - 1)
        quickSort(left + 1, rightBound)
    }

    quickSort(0, arr.lastIndex)
    return arr
}

fun check(n: Int): Boolean {
    var number = n
    var sum = 0
    while (number > 0) {
        sum += number % 10
        number /= 10
    }
    return sum == 10
}

private class FastScanner(private val input: InputStream) {
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextInt(): Int {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32 && c != -1)

        var sign = 1
        if (c == '-'.code) {
            sign = -1
            c = readByte()
        }

        var value = 0
        while (c > 32 && c != -1) {
            value = value * 10 + c - '0'.code
            c = readByte()
        }
        return value * sign
    }
}

fun solution(input: InputStream, output: OutputStream) {
    val reader = FastScanner(input)
    var k = reader.nextInt()
    var i = 19

    while (k > 0) {
        if (check(i)) {
            k--
        }
        if (k == 0) {
            output.write("$i\n".toByteArray())
            return
        }
        i++
    }
}

fun main() {
    val input = BufferedInputStream(System.`in`, 1024 * 1024)
    val output = BufferedOutputStream(System.out, 1024 * 1024)
    solution(input, output)
    output.flush()
}

